import assert from 'node:assert/strict';
import {existsSync,readFileSync} from 'node:fs';
import {capacityFor,frontloadLimit,isVisible,migrateBackup,monthlyAllowance,monthlyLogged,monthlyPlan,parseHours,projectMetrics,shiftWeek,weekKeyFor,weeklyPlan,weeklyResourcedHours} from '../src/lib/utils.js';
import {addablePhasesFor,taskLinesFor} from '../src/lib/taskLines.js';
import { hasPhases, isGeneralTask, phasesOf } from '../src/lib/tasks.js';
import { categoriseProjects } from '../src/lib/projectGrouping.js';
import {detectFormat,parseCSV,parseCSVLine,parseHoursMins} from '../src/lib/csvParser.js';
import {createProjectRecord,editProjectRecord,pinTaskLineRecord,removeTaskLineRecord,restoreProjectRecord,validateManagedProject,validateProjectDraft} from '../src/lib/projectOperations.js';
import {buildTimesheetCsv} from '../src/lib/csvExport.js';
import {entryNote,setEntryNoteRecord} from '../src/lib/entryNotes.js';
import {setEntryRecord,setTaskEntryRecord} from '../src/lib/projectOperations.js';
import {FILE_CHANGED_CODE,FILE_UNRESPONSIVE_CODE,backupPayload,readHandle,revisionsMatch,workspaceSignature,writeHandle} from '../src/lib/backupService.js';

const test=(name,fn)=>{try{fn();console.log(`✓ ${name}`)}catch(error){console.error(`✗ ${name}`);throw error}};
const asyncTest=async(name,fn)=>{try{await fn();console.log(`✓ ${name}`)}catch(error){console.error(`✗ ${name}`);throw error}};
const baseProject={id:'p1',name:'Boundary project',isBillable:true,resourcedHours:8,monthlyResourcedHours:null,entries:{},weeklyOverrides:{},frontloads:{},hiddenWeeks:[]};

test('strict time parsing accepts decimal and H:MM',()=>{assert.equal(parseHours('1:30').value,1.5);assert.equal(parseHours('7.6').value,7.6);assert.ok(parseHours('1:75').error);assert.ok(parseHours('-1').error)});
test('time parsing clears blanks and rejects more than a day',()=>{assert.equal(parseHours('  ').value,null);assert.ok(parseHours('24:01').error);assert.ok(parseHours('25').error);assert.equal(parseHours('0:15').value,.25)});
test('week shifting crosses year boundaries',()=>{assert.equal(shiftWeek('2025-12-29',1),'2026-01-05');assert.equal(weekKeyFor(new Date('2026-01-01T12:00:00')),'2025-12-29')});
test('monthly usage follows each actual entry date',()=>{const p={...baseProject,entries:{'2026-06-29':{0:2,2:3,4:1}}};assert.equal(monthlyLogged(p,'2026-06',{}),2);assert.equal(monthlyLogged(p,'2026-07',{}),4)});
test('monthly adjustments and remaining allowance are applied once',()=>{const p={...baseProject,monthlyResourcedHours:20,historicalMonthlyMonth:'2026-07',historicalMonthlyHours:3,entries:{'2026-07-13':{0:2,1:1}}};assert.equal(monthlyLogged(p,'2026-07',{}),6);assert.equal(monthlyAllowance(p,'2026-07-13',{}),17)});
test('leave reduces capacity and excludes logged time',()=>{const settings={visibleDays:[0,1,2],capacityByDay:[7.6,4,7.6,0,0,0,0],leaveWeeks:{'2026-07-13':[1]}};assert.equal(capacityFor('2026-07-13',settings),15.2);const p={...baseProject,entries:{'2026-07-13':{0:2,1:4}}};assert.equal(projectMetrics(p,'2026-07-13',settings.leaveWeeks).logged,2)});
test('weekly overrides and unlimited plans are deterministic',()=>{const p={...baseProject,weeklyOverrides:{'2026-07-13':3}};assert.equal(projectMetrics(p,'2026-07-13',{}).plan,3);assert.equal(projectMetrics({...p,resourcedHours:null,weeklyOverrides:{}},'2026-07-20',{}).status,'unlimited')});
test('allocation statuses cover under, at, over, and unlimited',()=>{assert.equal(projectMetrics({...baseProject,entries:{'2026-07-13':{0:2}}},'2026-07-13',{}).status,'under');assert.equal(projectMetrics({...baseProject,entries:{'2026-07-13':{0:8}}},'2026-07-13',{}).status,'at');assert.equal(projectMetrics({...baseProject,entries:{'2026-07-13':{0:9}}},'2026-07-13',{}).status,'over');assert.equal(projectMetrics({...baseProject,resourcedHours:null},'2026-07-13',{}).status,'unlimited')});
test('frontloading raises the receiving week and reduces the source week',()=>{const p={...baseProject,resourcedHours:5,frontloads:{'2026-07-13':3},entries:{'2026-07-13':{0:8}}},receiving=projectMetrics(p,'2026-07-13',{}),source=projectMetrics(p,'2026-07-20',{});assert.equal(receiving.frontloadedIn,3);assert.equal(receiving.weeklyAllowance,8);assert.equal(receiving.status,'at');assert.equal(source.frontloadedOut,3);assert.equal(source.weeklyAllowance,2)});
test('frontloading chains use each week’s net allowance',()=>{const p={...baseProject,resourcedHours:5,frontloads:{'2026-07-13':3,'2026-07-20':2}};assert.equal(projectMetrics(p,'2026-07-13',{}).weeklyAllowance,8);assert.equal(projectMetrics(p,'2026-07-20',{}).weeklyAllowance,4);assert.equal(projectMetrics(p,'2026-07-27',{}).weeklyAllowance,3);assert.equal(frontloadLimit(p,'2026-07-13'),7)});
test('weekly resourced hours use the net allowance after frontloading',()=>{const p={...baseProject,resourcedHours:12,frontloads:{'2026-07-06':4}};assert.equal(weeklyResourcedHours([p],'2026-07-13',{}),8)});
test('monthly allowance remains based on actual logged hours after frontloading',()=>{const p={...baseProject,resourcedHours:5,monthlyResourcedHours:6,frontloads:{'2026-07-13':3},entries:{'2026-07-13':{0:8}}},metrics=projectMetrics(p,'2026-07-13',{});assert.equal(monthlyLogged(p,'2026-07',{}),8);assert.equal(metrics.weeklyAllowance,8);assert.equal(metrics.effective,6);assert.equal(metrics.remaining,-2)});
test('frontload debt remains visible after a source plan is reduced',()=>{const p={...baseProject,resourcedHours:3,frontloads:{'2026-07-06':4}},metrics=projectMetrics(p,'2026-07-13',{});assert.equal(metrics.weeklyAllowance,-1);assert.equal(metrics.weeklyAvailable,0);assert.equal(metrics.status,'over');assert.equal(metrics.overDueToFrontloading,true)});
test('project scheduling and restoration rules are respected',()=>{assert.equal(isVisible({...baseProject,visibleOnwardsFrom:'2026-07-20'},'2026-07-13'),false);assert.equal(isVisible({...baseProject,hiddenWeeks:['2026-07-13']},'2026-07-13'),false);assert.equal(isVisible({...baseProject,archived:true},'2026-07-13'),false)});
test('legacy backups migrate without losing billability or entries',()=>{const migrated=migrateBackup({projects:[{name:'Legacy',isBillable:false,resourcedHours:4,entries:{'2026-06-08':{1:2}}}],settings:{visibleDays:[1,2,4]}});assert.equal(migrated.schemaVersion,3);assert.equal(migrated.projects[0].isBillable,false);assert.equal(migrated.projects[0].entries['2026-06-08'][1],2);assert.deepEqual(migrated.projects[0].frontloads,{});assert.deepEqual(migrated.settings.visibleDays,[1,2,4])});
test('original flat legacy task backups migrate entries and pinned rows',()=>{const migrated=migrateBackup({version:2,projects:[{id:'legacy-p',name:'Legacy Tasks',weeklyAllocation:6,tasks:[{id:'g',name:'General'},{id:'t1',name:'Discovery'}]}],entries:[{projectId:'legacy-p',taskId:'g',date:'2026-07-13',hours:1},{projectId:'legacy-p',taskId:'t1',date:'2026-07-14',hours:2.5}],weekRows:{'2026-07-13':['legacy-p::t1']}});const project=migrated.projects[0];assert.equal(project.resourcedHours,6);assert.equal(project.entries['2026-07-13'][0],1);assert.equal(project.taskEntries.t1['2026-07-13'][1],2.5);assert.deepEqual(project.taskRows['2026-07-13'],['t1']);assert.equal(projectMetrics(project,'2026-07-13',{}).logged,3.5)});
test('backup migration normalizes missing and malformed project fields',()=>{const migrated=migrateBackup({projects:[{name:undefined,entries:null,weeklyOverrides:[],frontloads:{'2026-07-13':2.555,'bad':4,'2026-07-14':3,'2026-07-20':-1},hiddenWeeks:'bad'}]});assert.equal(migrated.projects[0].name,'Untitled project 1');assert.deepEqual(migrated.projects[0].entries,{});assert.deepEqual(migrated.projects[0].weeklyOverrides,{});assert.deepEqual(migrated.projects[0].frontloads,{'2026-07-13':2.56});assert.deepEqual(migrated.projects[0].hiddenWeeks,[])});
const legacyBackupUrl=new URL('../Backups/TimeMaster.json',import.meta.url);
if(existsSync(legacyBackupUrl))test('provided legacy backup migrates every project',()=>{const raw=JSON.parse(readFileSync(legacyBackupUrl,'utf8'));const migrated=migrateBackup(raw);assert.equal(migrated.projects.length,10);assert.ok(migrated.projects.every(project=>project.id&&project.name&&project.entries));assert.ok(migrated.projects.some(project=>Object.keys(project.entries).length>0))});
test('backup payload carries schema, projects, settings, and timestamp',()=>{const payload=backupPayload([baseProject],{theme:'dark'});assert.equal(payload.schemaVersion,3);assert.equal(payload.projects[0].id,'p1');assert.equal(payload.settings.theme,'dark');assert.ok(!Number.isNaN(Date.parse(payload.exportedAt)))});
test('workspace signatures ignore export timestamps but retain data changes',()=>{const first=backupPayload([baseProject],{theme:'dark'}),second={...first,exportedAt:'2099-01-01T00:00:00.000Z'};assert.equal(workspaceSignature(first),workspaceSignature(second));assert.notEqual(workspaceSignature(first),workspaceSignature({...second,settings:{theme:'light'}}))});
test('file revisions require matching timestamp, size, and content hash',()=>{const revision={lastModified:1,size:100,contentHash:'abc'};assert.equal(revisionsMatch(revision,{...revision}),true);assert.equal(revisionsMatch(revision,{...revision,contentHash:'def'}),false);assert.equal(revisionsMatch(revision,null),false)});
test('project creation scopes set deterministic visibility',()=>{const fields={name:'New',hours:5,isBillable:true,monthly:null,historical:0,client:'',code:'',status:'active',color:'#000'};const weekOnly=createProjectRecord(fields,'week','2026-07-13','new','now');assert.equal(weekOnly.weeklyOverrides['2026-07-13'],5);assert.equal(weekOnly.hiddenOnwardsFrom,'2026-07-20');const next=createProjectRecord(fields,'next-onwards','2026-07-13','new2','now');assert.equal(next.visibleOnwardsFrom,'2026-07-20')});
test('one-time projects are limited to their temporary weeks and may be unlimited',()=>{const fields={name:'Temporary',hours:null,isBillable:true,monthly:null,historical:0,client:'',code:'',status:'active',color:'#000',projectType:'one-time',durationWeeks:0,durationDays:1,remainderLimit:null};const project=createProjectRecord(fields,'onwards','2026-07-13','temp','now');assert.equal(project.projectType,'one-time');assert.equal(project.weeklyOverrides['2026-07-13'],null);assert.equal(project.hiddenOnwardsFrom,'2026-07-20');assert.equal(isVisible(project,'2026-07-13'),true);assert.equal(isVisible(project,'2026-07-20'),false);assert.equal(projectMetrics(project,'2026-07-13',{}).status,'unlimited')});
test('converting to temporary starts now and preserves past allocation history',()=>{const p={...baseProject,visibleOnwardsFrom:'2026-06-01',weeklyOverrides:{'2026-07-06':6,'2026-07-20':10}};const fields={name:p.name,hours:4,isBillable:true,monthly:null,historical:0,client:'',code:'',status:'active',color:'#000',projectType:'one-time',durationWeeks:1,durationDays:0,remainderLimit:null};const changed=editProjectRecord(p,fields,'onwards','2026-07-13');assert.equal(changed.visibleOnwardsFrom,'2026-07-13');assert.equal(changed.hiddenOnwardsFrom,'2026-07-20');assert.deepEqual(changed.weeklyOverrides,{'2026-07-06':6,'2026-07-13':4})});
test('converting a temporary project to standard clears its expiry and generated overrides',()=>{const p={...baseProject,projectType:'one-time',visibleOnwardsFrom:'2026-07-13',hiddenOnwardsFrom:'2026-07-20',resourcedHours:null,weeklyOverrides:{'2026-07-13':4}};const fields={name:p.name,hours:6,isBillable:true,monthly:null,historical:0,client:'',code:'',status:'active',color:'#000',projectType:'standard'};const changed=editProjectRecord(p,fields,'onwards','2026-07-13');assert.equal(changed.hiddenOnwardsFrom,null);assert.equal(changed.resourcedHours,6);assert.deepEqual(changed.weeklyOverrides,{});assert.equal(isVisible(changed,'2026-07-20'),true)});
test('this-week edits preserve base and other overrides',()=>{const p={...baseProject,weeklyOverrides:{'2026-07-06':6,'2026-07-20':10}};const changed=editProjectRecord(p,{name:p.name,hours:3,isBillable:true,monthly:null,historical:0,client:'',code:'',status:'active',color:'#000'},'week','2026-07-13');assert.equal(changed.resourcedHours,8);assert.deepEqual(changed.weeklyOverrides,{'2026-07-06':6,'2026-07-13':3,'2026-07-20':10})});
test('onwards edits preserve known past plans and replace future plans',()=>{const p={...baseProject,entries:{'2026-07-06':{0:1},'2026-07-20':{0:1}},weeklyOverrides:{'2026-07-20':10}};const changed=editProjectRecord(p,{name:p.name,hours:4,isBillable:true,monthly:null,historical:0,client:'',code:'',status:'active',color:'#000'},'onwards','2026-07-13');assert.equal(changed.resourcedHours,4);assert.equal(changed.weeklyOverrides['2026-07-06'],8);assert.equal(changed.weeklyOverrides['2026-07-20'],undefined);assert.equal(weeklyPlan(changed,'2026-07-20'),4)});
test('monthly allocation respects the selected edit timeframe',()=>{const p={...baseProject,monthlyResourcedHours:10,entries:{'2026-07-06':{0:1},'2026-07-20':{0:1}}},fields={name:p.name,hours:8,isBillable:true,monthly:15.6,historical:0,client:'',code:'',status:'active',color:'#000'};const onwards=editProjectRecord(p,fields,'onwards','2026-07-13');assert.equal(monthlyPlan(onwards,'2026-07-06'),10);assert.equal(monthlyPlan(onwards,'2026-07-13'),15.6);assert.equal(monthlyPlan(onwards,'2026-07-20'),15.6);const oneWeek=editProjectRecord(p,fields,'week','2026-07-13');assert.equal(monthlyPlan(oneWeek,'2026-07-06'),10);assert.equal(monthlyPlan(oneWeek,'2026-07-13'),15.6);assert.equal(monthlyPlan(oneWeek,'2026-07-20'),10)});
test('onwards edits preserve task-only historical weeks',()=>{const p={...baseProject,taskEntries:{t1:{'2026-07-06':{0:2}}}};const changed=editProjectRecord(p,{name:p.name,hours:4,isBillable:true,monthly:null,historical:0,client:'',code:'',status:'active',color:'#000'},'onwards','2026-07-13');assert.equal(changed.weeklyOverrides['2026-07-06'],8)});
test('onwards edits retain frontloads and preserve their historical plans',()=>{const p={...baseProject,frontloads:{'2026-07-06':3}};const changed=editProjectRecord(p,{name:p.name,hours:4,isBillable:true,monthly:null,historical:0,client:'',code:'',status:'active',color:'#000'},'onwards','2026-07-13');assert.equal(changed.frontloads['2026-07-06'],3);assert.equal(weeklyPlan(changed,'2026-07-06'),8)});
test('retrospective edits change only known prior weeks',()=>{const p={...baseProject,entries:{'2026-07-06':{0:1},'2026-07-13':{0:1}},weeklyOverrides:{'2026-07-20':10}};const changed=editProjectRecord(p,{name:p.name,hours:2,isBillable:true,monthly:null,historical:0,client:'',code:'',status:'active',color:'#000'},'retro','2026-07-13');assert.equal(changed.weeklyOverrides['2026-07-06'],2);assert.equal(changed.weeklyOverrides['2026-07-20'],10);assert.equal(changed.resourcedHours,8)});
test('entire-project edits clear week-specific allocation overrides',()=>{const p={...baseProject,weeklyOverrides:{'2026-07-13':3}};const changed=editProjectRecord(p,{name:p.name,hours:6,isBillable:false,monthly:20,historical:1,client:'Client',code:'C1',status:'on-hold',color:'#123'},'project','2026-07-13');assert.equal(changed.resourcedHours,6);assert.deepEqual(changed.weeklyOverrides,{});assert.equal(changed.isBillable,false);assert.equal(changed.status,'on-hold')});
test('existing archived projects restore without duplication',()=>{const p={...baseProject,archived:true,hiddenOnwardsFrom:'2026-07-06',hiddenWeeks:['2026-07-13']};const fields={name:p.name,hours:7,isBillable:true,monthly:null,historical:0,client:'',code:'',status:'active',color:'#000'};const restored=restoreProjectRecord(p,fields,'onwards','2026-07-13');assert.equal(restored.archived,false);assert.equal(restored.hiddenOnwardsFrom,null);assert.equal(restored.visibleOnwardsFrom,'2026-07-13');assert.equal(restored.resourcedHours,7)});
test('managed project validation rejects blank, negative, and duplicate values',()=>{const projects=[baseProject,{...baseProject,id:'p2',name:'Other'}];assert.ok(validateManagedProject(projects,'p1','  ',4).error);assert.ok(validateManagedProject(projects,'p1','Valid',-1).error);assert.ok(validateManagedProject(projects,'p1','other',4).error);assert.deepEqual(validateManagedProject(projects,'p1',' Renamed ','6.5'),{name:'Renamed',hours:6.5})});
test('full project validation accepts zero and unlimited allocations',()=>{assert.deepEqual(validateProjectDraft({name:'Zero',unlimited:false,hours:'0',monthlyHours:'0',historicalMonthly:'0'}),{});assert.deepEqual(validateProjectDraft({name:'Unlimited',unlimited:true,hours:'',monthlyHours:'',historicalMonthly:''}),{});assert.ok(validateProjectDraft({name:'Bad',unlimited:false,hours:'-1',monthlyHours:'',historicalMonthly:''}).hours)});
test('one-time project validation requires whole, valid duration values',()=>{assert.ok(validateProjectDraft({name:'Bad',unlimited:true,hours:'',monthlyHours:'',historicalMonthly:'',projectType:'one-time',durationWeeks:-1,durationDays:1}).duration);assert.ok(validateProjectDraft({name:'Bad',unlimited:true,hours:'',monthlyHours:'',historicalMonthly:'',projectType:'one-time',durationWeeks:1.5,durationDays:0}).duration);assert.ok(validateProjectDraft({name:'Bad',unlimited:true,hours:'',monthlyHours:'',historicalMonthly:'',projectType:'one-time',durationWeeks:1,durationDays:7}).duration);assert.deepEqual(validateProjectDraft({name:'Good',unlimited:true,hours:'',monthlyHours:'',historicalMonthly:'',projectType:'one-time',durationWeeks:0,durationDays:1}),{})});
test('CSV helpers parse quoting, hour-minute values, and format markers',()=>{assert.deepEqual(parseCSVLine('"A, B","He said ""yes""",3'),['A, B','He said "yes"','3']);assert.equal(parseHoursMins('1:30'),1.5);assert.equal(detectFormat('\ufeffTimeCode,Mon 13 Jan,Total Logged Hours'),'timesheet');assert.equal(detectFormat('Project Name,Resourced Hours'),'resourcing')});
test('timesheet CSV export is chronological, quoted, and task-compatible',()=>{const csv=buildTimesheetCsv([{...baseProject,name:'Alpha, Project',client:'Client "A"',code:'A1',entries:{'2026-07-13':{2:1.5,0:2}},tasks:[{id:'general',name:'General'},{id:'t1',name:'Discovery'}],taskEntries:{t1:{'2026-07-13':{1:3}}}}]);const lines=csv.split('\r\n');assert.equal(lines[0],'Date,Day,Project,Client,Code,Task,Hours,Notes');assert.equal(lines[1],'2026-07-13,Mon,"Alpha, Project","Client ""A""",A1,General,2,');assert.equal(lines[2],'2026-07-14,Tue,"Alpha, Project","Client ""A""",A1,Discovery,3,');assert.equal(lines[3],'2026-07-15,Wed,"Alpha, Project","Client ""A""",A1,General,1.5,')});
test('task time contributes to weekly and monthly totals',()=>{const project={...baseProject,entries:{'2026-07-13':{0:1}},tasks:[{id:'general',name:'General'},{id:'t1',name:'Delivery'}],taskEntries:{t1:{'2026-07-13':{1:2,2:3}}}};assert.equal(projectMetrics(project,'2026-07-13',{}).logged,6);assert.equal(monthlyLogged(project,'2026-07',{}),6)});
test('orphaned task time is not added to visible timesheet totals',()=>{const project={...baseProject,entries:{'2026-07-13':{0:.25}},tasks:[{id:'general',name:'General'}],taskEntries:{deletedTask:{'2026-07-13':{0:6}}}};assert.equal(projectMetrics(project,'2026-07-13',{}).logged,.25);assert.equal(monthlyLogged(project,'2026-07',{}),.25)});
test('removing a project task prunes its time and pinned rows',()=>{const project={...baseProject,tasks:[{id:'general',name:'General'},{id:'t1',name:'Old task'}],taskEntries:{t1:{'2026-07-13':{0:2}}},taskRows:{'2026-07-13':['t1']}};const fields={name:project.name,hours:8,isBillable:true,monthly:null,historical:0,client:'',code:'',status:'active',color:'#000',tasks:[{id:'general',name:'General'}]};const changed=editProjectRecord(project,fields,'project','2026-07-13');assert.deepEqual(changed.taskEntries,{});assert.deepEqual(changed.taskRows['2026-07-13'],[])});
test('task lines pin once and remove only the selected week',()=>{const project={...baseProject,taskRows:{'2026-07-13':['t1']},taskEntries:{t1:{'2026-07-13':{0:2},'2026-07-20':{0:3}}}};const pinned=pinTaskLineRecord(project,'t1','2026-07-13');assert.deepEqual(pinned.taskRows['2026-07-13'],['t1']);const removed=removeTaskLineRecord(pinned,'t1','2026-07-13');assert.deepEqual(removed.taskRows['2026-07-13'],[]);assert.equal(removed.taskEntries.t1['2026-07-13'],undefined);assert.equal(removed.taskEntries.t1['2026-07-20'][0],3)});
test('phase lines and addable phases hide phases already on the week',()=>{const project={...baseProject,tasks:[{id:'general',name:'General'},{id:'t2',name:'Build'},{id:'t1',name:'Design'},{id:'t3',name:'general'}],taskRows:{'2026-07-13':['t2']},taskEntries:{}};assert.deepEqual(taskLinesFor(project,'2026-07-13').map(task=>task.id),['t2']);assert.deepEqual(addablePhasesFor(project,'2026-07-13').map(task=>task.id),['t1']);assert.deepEqual(addablePhasesFor({...project,taskRows:{'2026-07-13':['t2','t1']}},'2026-07-13'),[]);assert.deepEqual(addablePhasesFor(project,'2026-07-20').map(task=>task.id),['t2','t1']);assert.deepEqual(taskLinesFor({...project,taskRows:{},taskEntries:{t1:{'2026-07-13':{0:1}}}},'2026-07-13').map(task=>task.id),['t1'])});
test('General is recognized by reserved ID or case-insensitive name', () => {
  const byId = { id: 'general', name: 'Unassigned' };
  const byName = { id: 'legacy-general', name: 'gEnErAl' };
  const design = { id: 'design', name: 'Design' };
  const build = { id: 'build', name: 'Build' };
  const project = { tasks: [byId, design, byName, build] };
  assert.equal(isGeneralTask(byId), true);
  assert.equal(isGeneralTask(byName), true);
  assert.equal(isGeneralTask(design), false);
  assert.deepEqual(phasesOf(project), [design, build]);
  assert.equal(hasPhases(project), true);
  assert.equal(hasPhases({ tasks: [byId, byName] }), false);
  assert.equal(hasPhases({}), false);
  assert.deepEqual(phasesOf({}), []);
});

test('phase lines combine pinned and logged tasks in phase order for the selected week', () => {
  const week = '2026-07-13';
  const project = {
    tasks: [
      { id: 'design', name: 'Design' },
      { id: 'build', name: 'Build' },
      { id: 'review', name: 'Review' },
      { id: 'general', name: 'General' },
      { id: 'legacy-general', name: 'GENERAL' },
    ],
    taskRows: { [week]: ['design', 'design', 'general', 'missing'] },
    taskEntries: {
      build: { [week]: { 0: 2 } },
      review: { [week]: { 0: 0 }, '2026-07-20': { 1: 1 } },
      'legacy-general': { [week]: { 0: 3 } },
      missing: { [week]: { 0: 4 } },
    },
  };
  assert.deepEqual(taskLinesFor(project, week).map(({ id }) => id), ['design', 'build']);
  assert.deepEqual(taskLinesFor(project, '2026-07-20').map(({ id }) => id), ['review']);
  assert.deepEqual(taskLinesFor({}, week), []);
});

test('project groups preserve project order and sort status, client and billability groups', () => {
  const projects = [
    { id: 'closed', status: 'closed', client: ' Beta ', isBillable: false },
    { id: 'default', client: 'alpha' },
    { id: 'held', status: 'on-hold', client: 'BETA', isBillable: false },
    { id: 'active', status: 'active', isBillable: true },
  ];
  const grouped = (category) => categoriseProjects(projects, category).map(
    ({ label, projects: members }) => [label, members.map(({ id }) => id)],
  );
  assert.deepEqual(grouped('none'), [['All projects', projects.map(({ id }) => id)]]);
  assert.deepEqual(grouped('status'), [
    ['Active', ['default', 'active']],
    ['On hold', ['held']],
    ['Closed', ['closed']],
  ]);
  assert.deepEqual(grouped('client'), [
    ['alpha', ['default']],
    ['Beta', ['closed', 'held']],
    ['No client', ['active']],
  ]);
  assert.deepEqual(grouped('billability'), [
    ['Billable', ['default', 'active']],
    ['Non-billable', ['closed', 'held']],
  ]);
});

test('usage groups follow the selected week and leave', () => {
  const week = '2026-07-13';
  const projects = [
    { ...baseProject, id: 'unlimited', resourcedHours: null },
    { ...baseProject, id: 'under', entries: { [week]: { 0: 4 } } },
    { ...baseProject, id: 'at', entries: { [week]: { 1: 8 } } },
    { ...baseProject, id: 'over', entries: { [week]: { 0: 10 } } },
  ];
  const groups = (leaveWeeks) => categoriseProjects(projects, 'usage', week, leaveWeeks)
    .map(({ key, label, projects: members }) => [key, label, members.map(({ id }) => id)]);
  assert.deepEqual(groups({}), [
    ['over', 'Over allocation', ['over']],
    ['at', 'At allocation', ['at']],
    ['under', 'Allowance left', ['under']],
    ['unlimited', 'Unlimited', ['unlimited']],
  ]);
  assert.deepEqual(groups({ [week]: [0] }), [
    ['at', 'At allocation', ['at']],
    ['under', 'Allowance left', ['under', 'over']],
    ['unlimited', 'Unlimited', ['unlimited']],
  ]);
});

