const B=await import('../src/lib/budget.js');
const N=await import('../src/lib/entryNotes.js');
const ops=await import('../src/lib/projectOperations.js');
const W='2026-07-13';
const acts=[{id:'qrg',name:'Quick reference guides (QRGs)',amount:4000},{id:'ug',name:'User guide',amount:3000}];
const sp=(extra={})=>({id:'s1',name:'Split',budget:20000,resourcedHours:10,tasks:[{id:'general',name:'General'},{id:'t1',name:'Docs'}],entries:{},taskEntries:{t1:{[W]:{0:5}}},weeklyOverrides:{},frontloads:{},hiddenWeeks:[],hiddenOnwardsFrom:'2026-07-27',activities:acts,...extra});
test('a split tag costs each share and keeps project totals single-counted',()=>{const p=sp({activityTags:{t1:{[W]:{0:{qrg:3,ug:2}}}}});const f=B.projectFinance(p,{hourlyRate:150},W);assert.equal(f.spent,750);assert.equal(f.activities[0].spent,450);assert.equal(f.activities[1].spent,300);assert.equal(f.activities[0].hours,3);assert.equal(f.unlinked.hours,0);assert.equal(f.review.length,0);const rows=B.weekCostRows(p,{hourlyRate:150},W,{by:'activity'});assert.deepEqual(rows.map(r=>[r.id,r.cost]),[['qrg',450],['ug',300]]);assert.equal(B.weekCostRows(p,{hourlyRate:150},W)[1].cost,750)});
test('a note naming several activities is split automatically',()=>{const p=sp({notes:{t1:{[W]:{0:'3 QRGs and a user guide'}}}});const f=B.projectFinance(p,{hourlyRate:100},W);assert.equal(f.activities[0].hours+f.activities[1].hours,5);assert.ok(f.activities[0].hours>f.activities[1].hours);assert.equal(f.activities[0].spent+f.activities[1].spent,500)});
test('editing the hours rescales a stored split proportionally',()=>{const p=ops.setTaskEntryRecord(sp({activityTags:{t1:{[W]:{0:{qrg:3,ug:2}}}}}),'t1',W,0,10);const f=B.projectFinance(p,{hourlyRate:100},W);assert.equal(f.activities[0].hours,6);assert.equal(f.activities[1].hours,4);assert.equal(f.spent,1000);const norm=B.normaliseProjectFinance(p);assert.deepEqual(norm.activityTags.t1[W][0],{qrg:6,ug:4});assert.equal(N.entryActivityTag(ops.setTaskEntryRecord(p,'t1',W,0,null),'t1',W,0),null)});
test('deleting an activity moves its share to the General bucket',()=>{const p=sp({activityTags:{t1:{[W]:{0:{qrg:3,ug:2}}}}});const edited=B.applyProjectFinance(p,{budget:20000,phaseBudgets:{},activities:[acts[0]]});assert.deepEqual(edited.activityTags.t1[W][0],{qrg:3,none:2});const f=B.projectFinance(edited,{hourlyRate:100},W);assert.equal(f.activities[0].spent,300);assert.equal(f.unlinked.hours,2);assert.equal(f.unlinked.spent,200);assert.equal(f.generalCosting.spent,200);assert.equal(f.review.length,0);const whole=B.applyProjectFinance(sp({activityTags:{t1:{[W]:{0:'ug'}}}}),{budget:1,activities:[acts[0]]});assert.deepEqual(whole.activityTags.t1[W][0],{none:5})});
test('split shares are rounded to the cent and add up to the entry',()=>{const p=sp({taskEntries:{t1:{[W]:{0:1}}},activityTags:{t1:{[W]:{0:{qrg:0.33,ug:0.67}}}}});const f=B.projectFinance(p,{hourlyRate:33.33},W);assert.equal(f.spent,33.33);assert.equal(Math.round((f.activities[0].spent+f.activities[1].spent)*100),3333);assert.equal(f.activities[0].spent,11)});
